        });
        setPublishFile(null);
        setModalError(null);
        setIsModalOpen(true);
    };

    const handlePublishSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedDoc || !publishFile) {
            setModalError("Debes adjuntar el archivo PDF para la publicación.");
            return;
        }

        setIsPublishing(true);
        setModalError(null);

        try {
            await publishProcedure({
                title: selectedDoc.name,
                code: publishForm.code,
                area: publishForm.area,
                version: publishForm.version,
                status: publishForm.status,
                uad_origin_id: selectedDoc.id,
                file: publishFile
            });
            await fetchProcedures(); // Refresh list safely
            setIsModalOpen(false);
        } catch (err) {
            setModalError(err instanceof Error ? err.message : "Error desconocido al publicar.");
        } finally {
            setIsPublishing(false);
        }
    };

    const handleUnpublish = async (procId: string) => {
        if (!window.confirm("¿Estás seguro de que quieres eliminar este procedimiento de NEXUS?")) return;
        try {
            await unpublishProcedure(procId);
            setPublishedProcedures(prev => prev.filter(p => p.id !== procId));
        } catch (err) {
