    const remoteDocs = useMemo(() => {
        if (!searchTerm) return publishedProcedures;
        return publishedProcedures.filter(p => p.title.toLowerCase().includes(searchTerm.toLowerCase()) || p.code.toLowerCase().includes(searchTerm.toLowerCase()));
