                        <span className="bg-purple-900/30 border border-purple-800 text-purple-300 px-2 py-0.5 rounded-full">{remoteDocs.length}</span>
                    </div>
                    <div className="flex-1 overflow-y-auto p-2 space-y-2 bg-black/20">
