                                    </div>
                                    <span className={`text-[10px] uppercase font-bold px-1.5 py-0.5 rounded ${proc.status === 'Vigente' ? 'text-green-400 bg-green-900/20' : 'text-red-400 bg-red-900/20'}`}>{proc.status}</span>
