                                            value={publishForm.code}
                                            onChange={e => setPublishForm({...publishForm, code: e.target.value})}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-400 mb-1">Versión</label>
                                        <input 
                                            type="text" 
                                            required
                                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white focus:border-brand-primary outline-none"
                                            value={publishForm.version}
                                            onChange={e => setPublishForm({...publishForm, version: e.target.value})}
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1">Área Destino (Nexus)</label>
                                    <select 
                                        className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-white focus:border-brand-primary outline-none"
                                        value={publishForm.area}
                                        onChange={e => setPublishForm({...publishForm, area: e.target.value})}
                                    >
                                        {AREAS.map(area => <option key={area} value={area}>{area}</option>)}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1">Archivo Físico (PDF)</label>
                                    <div className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center cursor-pointer hover:bg-gray-700/50 transition-colors relative">
                                        <input 
                                            type="file" 
                                            accept=".pdf"
                                            className="absolute inset-0 opacity-0 cursor-pointer"
                                            onChange={e => setPublishFile(e.target.files?.[0] || null)}
                                        />
                                        {publishFile ? (
                                            <div className="text-green-400 flex items-center justify-center gap-2">
                                                <CheckCircleIcon className="h-5 w-5"/> {publishFile.name}
                                            </div>
                                        ) : (
                                            <div className="text-gray-400 text-sm">
                                                <UploadIcon className="h-6 w-6 mx-auto mb-1"/>
                                                Arrastra o click para seleccionar PDF
                                            </div>
                                        )}
                                    </div>
                                    <p className="text-[10px] text-gray-500 mt-1">* Se subirá una copia al servidor externo.</p>
                                </div>

                                {modalError && <div className="text-red-400 text-sm bg-red-900/20 p-2 rounded border border-red-800">{modalError}</div>}
                            </div>

                            <div className="p-4 border-t border-gray-700 bg-gray-900 flex justify-end gap-3">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 rounded text-gray-400 hover:text-white hover:bg-gray-800">Cancelar</button>
                                <button 
                                    type="submit" 
                                    disabled={isPublishing}
                                    className="px-6 py-2 rounded bg-brand-primary hover:bg-brand-secondary text-white font-bold flex items-center gap-2 disabled:opacity-50"
                                >
                                    {isPublishing && <Spinner size="sm"/>}
                                    {isPublishing ? 'Publicando...' : 'Confirmar Publicación'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

