                                        className={`relative inline-flex h-5 w-9 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${isLive ? 'bg-brand-primary' : 'bg-gray-600'} ${isProcessing ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    >
                                        <span
                                            aria-hidden="true"
                                            className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${isLive ? 'translate-x-4' : 'translate-x-0'}`}
                                        />
                                    </button>
