            {/* DUAL PANE LAYOUT */}
            <div className="flex-1 flex gap-6 overflow-hidden min-h-0">
                {renderTable(filteredLocalDocs, localPublished, 'local')}
                {renderTable(filteredExternalDocs, externalPublished, 'external')}
            </div>

            {/* AUTH MODAL */}
            {isModalOpen && targetDoc && (
                <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
