const AREAS = [
    "Proyectos y Mejora Continua", "Mensajeria y Distribucion", "Calidad", "Almacen C", 
    "Empaque Retail", "Empaque TV", "Devoluciones", "Inventarios", "Recibo", 
    "Reacondicionado", "Maquila", "Tecnologías de la Información", "Recursos Humanos"
];

// Helper to build folder tree
const buildFolderTree = (folders: Folder[]): Folder[] => {
    if (!folders || folders.length === 0) return [];
    const folderMap = new Map<string, Folder & { children: Folder[] }>();
    folders.forEach(folder => folderMap.set(folder.id, { ...folder, children: [] }));
    const rootNodes: (Folder & { children: Folder[] })[] = [];
    folderMap.forEach(node => {
        if (node.parentId && folderMap.has(node.parentId)) {
            folderMap.get(node.parentId)!.children.push(node);
        } else {
            rootNodes.push(node);
        }
    });
    const sortChildrenRecursively = (node: Folder & { children: Folder[] }) => {
        if (node.children && node.children.length > 0) {
            node.children.sort((a, b) => a.name.localeCompare(b.name));
            node.children.forEach(sortChildrenRecursively);
        }
    };
    rootNodes.sort((a, b) => {
        if (a.name === 'General') return -1;
        if (b.name === 'General') return 1;
        return a.name.localeCompare(b.name);
    });
    rootNodes.forEach(sortChildrenRecursively);
    return rootNodes;
};

