    const fetchData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [localProcs, extProcs, localFolders, extFolders] = await Promise.all([
                getLocalPublishedProcedures(),
                getExternalPublishedProcedures(),
                getLocalPublishedFolders(),
                getExternalPublishedFolders()
            ]);
            setLocalPublished(localProcs);
            setExternalPublished(extProcs);
            setLocalPublishedFolders(new Set(localFolders.map(f => f.origin_folder_id)));
            setExternalPublishedFolders(new Set(extFolders.map(f => f.origin_folder_id)));
        } catch (error) {
            console.error("Error loading nexus status", error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // Initial expansion
    useEffect(() => {
        const initialExpanded = new Set<string>();
        const genLocal = folders.find(f => f.name === 'General');
        const genExt = externalFolders.find(f => f.name === 'General');
        if (genLocal) initialExpanded.add(genLocal.id);
        if (genExt) initialExpanded.add(genExt.id);
        setExpandedFolders(initialExpanded);
