    const toggleFolderExpand = (folderId: string) => {
        setExpandedFolders(prev => {
            const next = new Set(prev);
            if (next.has(folderId)) next.delete(folderId);
            else next.add(folderId);
            return next;
        });
    };

    // --- ACTIONS ---
    const handleToggleDoc = useCallback((doc: AppDocument, source: 'local' | 'external', currentStatus: PublishedProcedure | undefined) => {
        if (currentStatus) {
            if (!window.confirm(`¿Retirar acceso a "${doc.name}"?`)) return;
            setIsProcessing(true);
            const action = source === 'local' ? unpublishLocalProcedure : unpublishExternalProcedure;
            action(currentStatus.id)
                .then(() => {
                    if (source === 'local') setLocalPublished(prev => prev.filter(p => p.id !== currentStatus.id));
                    else setExternalPublished(prev => prev.filter(p => p.id !== currentStatus.id));
                })
                .catch(err => alert(err.message))
                .finally(() => setIsProcessing(false));
        } else {
            setTargetItem({ type: 'doc', item: doc });
            setTargetDb(source);
            setPublishForm({ code: '', area: AREAS[0], version: '1.0' });
            setModalError(null);
            setIsModalOpen(true);
