                    storage_path: doc.storagePath,
                    folder_id: doc.folderId
                };
                if (targetDb === 'local') await publishLocalProcedure(payload);
                else await publishExternalProcedure(payload);

            } else {
                // Folder Publishing Logic (Batch)
                const folder = targetItem.item as Folder;
                // 1. Publish the folder record with NAME
                if (targetDb === 'local') await publishLocalFolder(folder.id, folder.name, publishForm.area);
                else await publishExternalFolder(folder.id, folder.name, publishForm.area);

                // 2. Batch publish documents inside this folder
                const docsInFolder = (targetDb === 'local' ? documents : externalDocuments).filter(d => d.folderId === folder.id);

                const promises = docsInFolder.map(doc => {
                    const payload = {
                        title: doc.name,
                        code: publishForm.code, 
                        area: publishForm.area,
                        version: publishForm.version,
                        status: 'Vigente',
                        origin_id: doc.id,
                        storage_path: doc.storagePath,
                        folder_id: doc.folderId 
                    };
                    return targetDb === 'local' ? publishLocalProcedure(payload) : publishExternalProcedure(payload);
                });

                await Promise.allSettled(promises);
            }

            await fetchData();
            setIsModalOpen(false);
        } catch (err) {
            setModalError(err instanceof Error ? err.message : "Error desconocido.");
        } finally {
            setIsProcessing(false);
        }
    };

