                        className="w-full bg-gray-900 border border-gray-700 rounded-lg py-2 pl-10 pr-4 text-sm focus:border-brand-primary focus:outline-none"
                    />
                    <SearchIcon className="absolute left-3 top-2.5 h-4 w-4 text-gray-500" />
                </div>
            </div>

            {/* DUAL PANE LAYOUT */}
            <div className="flex-1 flex gap-6 overflow-hidden min-h-0">
                {renderPanel(documents, folders, localPublished, localPublishedFolders, 'local')}
                {renderPanel(externalDocuments || [], externalFolders || [], externalPublished, externalPublishedFolders, 'external')}
            </div>

            {/* AUTH MODAL */}
            {isModalOpen && targetItem && (
                <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                    <div className="bg-gray-800 w-full max-w-sm rounded-xl border border-gray-600 shadow-2xl overflow-hidden animate-fade-in">
                        <form onSubmit={handleConfirmPublish}>
                            <div className={`p-4 border-b border-gray-700 flex justify-between items-center ${targetDb === 'local' ? 'bg-blue-900/20' : 'bg-purple-900/20'}`}>
                                <h3 className="font-bold text-base text-white flex items-center gap-2">
                                    {targetDb === 'local' ? <ServerIcon className="h-4 w-4"/> : <DatabaseIcon className="h-4 w-4"/>}
                                    Autorizar en DB {targetDb === 'local' ? '1' : '2'}
                                </h3>
                                <button type="button" onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-white"><XCircleIcon className="h-5 w-5"/></button>
                            </div>

                            <div className="p-5 space-y-4">
                                <div className="text-xs text-gray-400 p-2 bg-gray-900 rounded border border-gray-700 truncate">
                                    {targetItem.type === 'doc' ? 'Documento:' : 'Carpeta:'} <span className="text-gray-200 font-bold">{targetItem.item.name}</span>
                                </div>
                                {targetItem.type === 'folder' && (
                                    <p className="text-xs text-yellow-500 bg-yellow-900/20 p-2 rounded border border-yellow-800/50">
                                        Nota: Al publicar esta carpeta, todos sus documentos internos se harán visibles automáticamente.
                                    </p>
                                )}

                                <div>
                                    <label className="block text-xs font-bold text-gray-400 mb-1">Área Destino</label>
                                    <select 
                                        className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white focus:border-brand-primary outline-none"
                                        value={publishForm.area}
                                        onChange={e => setPublishForm({...publishForm, area: e.target.value})}
                                    >
                                        {AREAS.map(area => <option key={area} value={area}>{area}</option>)}
                                    </select>
                                </div>

                                <div className="grid grid-cols-2 gap-3">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-400 mb-1">Código {targetItem.type === 'folder' ? '(Prefijo)' : ''}</label>
                                        <input 
                                            type="text" 
                                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white outline-none focus:border-brand-primary"
                                            value={publishForm.code}
                                            onChange={e => setPublishForm({...publishForm, code: e.target.value})}
                                            placeholder={targetItem.type === 'folder' ? "Opcional" : "Ej: IT-01"}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-400 mb-1">Versión</label>
                                        <input 
                                            type="text" 
                                            className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white outline-none focus:border-brand-primary"
                                            value={publishForm.version}
                                            onChange={e => setPublishForm({...publishForm, version: e.target.value})}
                                        />
                                    </div>
                                </div>

                                {modalError && <div className="text-red-400 text-xs bg-red-900/20 p-2 rounded border border-red-800">{modalError}</div>}
                            </div>

                            <div className="p-4 border-t border-gray-700 bg-gray-900 flex justify-end gap-3">
                                <button type="button" onClick={() => setIsModalOpen(false)} className="px-3 py-1.5 rounded text-xs text-gray-400 hover:text-white hover:bg-gray-800">Cancelar</button>
                                <button 
                                    type="submit" 
                                    disabled={isProcessing}
                                    className="px-4 py-1.5 rounded text-xs bg-brand-primary hover:bg-brand-secondary text-white font-bold flex items-center gap-2 disabled:opacity-50"
                                >
                                    {isProcessing && <Spinner size="sm"/>}
                                    Confirmar
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default NexusView;
